<template><ElSpace direction="vertical" fill class="v1-page" :size="20"><ElPageHeader title="天枢" content="运行总览" @back="$emit('navigate','overview')"><template #extra><ElButton @click="$emit('navigate','prediction')">开始预测</ElButton></template></ElPageHeader>
 <ElRow :gutter="20"><ElCol :xs="12" :lg="6" class="v1-card-col"><ElCard shadow="never"><ElStatistic title="当前功率" :value="snapshot.power_available?n(snapshot.power_kw,2):'暂无数据'" suffix="kW" /><ElSpace class="v1-gap"><ElTag>{{snapshot.power_complete?'完整':'部分'}}</ElTag><ElTag :type="snapshot.source==='simulated'?'warning':'info'">{{snapshot.source==='simulated'?'演示':'实测'}}</ElTag></ElSpace></ElCard></ElCol><ElCol :xs="12" :lg="6" class="v1-card-col"><ElCard shadow="never"><ElStatistic title="今日用电" :value="value(snapshot.totals.today_kwh,1)" suffix="kWh" /><ElTag class="v1-gap">{{snapshot.source==='simulated'?'演示':'估算'}}</ElTag></ElCard></ElCol><ElCol :xs="12" :lg="6" class="v1-card-col"><ElCard shadow="never"><ElStatistic title="今日费用" :value="value(snapshot.totals.today_cost,2)" prefix="¥" /><ElTag class="v1-gap">估算</ElTag></ElCard></ElCol><ElCol :xs="12" :lg="6" class="v1-card-col"><ElCard shadow="never"><ElStatistic title="待处理异常" :value="snapshot.pending_incidents??snapshot.alerts.length" :value-style="{color:snapshot.alerts.length?'var(--el-color-danger)':'var(--el-color-success)'}" /><ElButton text class="v1-gap" @click="$emit('navigate','alerts')">处理事件</ElButton></ElCard></ElCol></ElRow>
 <ElRow :gutter="20"><ElCol :span="14"><ElCard shadow="never"><template #header><ElSpace class="v1-spread"><strong>异常与处理</strong><ElButton text @click="$emit('navigate','alerts')">全部</ElButton></ElSpace></template><ElEmpty :image-size="80" v-if="!snapshot.alerts.length" description="暂无活动告警" /><ElSpace v-else direction="vertical" fill class="v1-page"><ElAlert v-for="a in snapshot.alerts.slice(0,5)" :key="a.id" :title="a.title" :type="a.machine_state==='unknown'?'warning':a.level==='critical'?'error':'warning'" show-icon :closable="false" @click="$emit('navigate','alerts')" /></ElSpace></ElCard></ElCol><ElCol :span="10"><ElCard shadow="never"><template #header>余额与处理时限</template><ElEmpty :image-size="80" v-if="!meters.length" description="暂无余额电表" /><ElSpace v-else direction="vertical" fill class="v1-page" :size="20"><ElDescriptions v-for="d in meters" :key="d.id" :title="d.name" :column="1" border><ElDescriptionsItem label="余额">{{value(d.api?.reading?.balance,2)}} kWh <ElTag :type="d.online?'success':'warning'">{{d.online?'实测':'过期'}}</ElTag></ElDescriptionsItem><ElDescriptionsItem label="预计可用">{{d.api?.forecast?.forecast?.available?value(d.api.forecast.forecast.remaining_hours,1)+' 小时':'学习中'}} <ElTag>估算</ElTag></ElDescriptionsItem><ElDescriptionsItem label="更新时间">{{date(d.api?.reading?.ts)}}</ElDescriptionsItem></ElDescriptions></ElSpace></ElCard></ElCol></ElRow>
 <ElCard shadow="never"><template #header><ElSpace class="v1-spread"><strong>实时功率 / kW</strong><ElSpace><ElTooltip content="鼠标悬停图内，滚轮缩放时间范围；持续跟随最新数据"><ElTag>{{rangeLabel}}</ElTag></ElTooltip><ElButton v-if="liveWindowSeconds!==180" text @click="liveWindowSeconds=180">恢复 3 分钟</ElButton><ElTag :type="snapshot.collector_healthy?'success':'danger'">{{snapshot.collector_healthy?'采集正常':'采集异常'}}</ElTag></ElSpace></ElSpace></template><ArtLineChart v-if="snapshot.trend.some(p=>p.kw!=null)" :live-window-seconds="liveWindowSeconds" :timestamps="snapshot.trend.map(p=>p.ts)" @window-change="liveWindowSeconds=$event" :data="snapshot.trend.map(p=>p.kw)" height="300px" :smooth="false" /><ElEmpty :image-size="80" v-else description="暂无实时功率" /></ElCard>
 <ElCard shadow="never"><template #header>计量与设备状态</template><ArtTable :data="snapshot.devices" height="340" :show-table-header="false"><ElTableColumn label="类型" width="80"><template #default="{row}"><ArtSvgIcon :icon="row.device_type?.includes('meter')?'ri:dashboard-3-line':'ri:plug-line'" class="v1-device-icon" /></template></ElTableColumn><ElTableColumn prop="name" label="设备" /><ElTableColumn prop="area" label="区域" /><ElTableColumn label="通信"><template #default="{row}"><ElTag :type="row.online?'success':'info'">{{row.communication==='online'?'在线':row.communication==='offline'?'离线':'未知'}}</ElTag></template></ElTableColumn><ElTableColumn label="数据时间" min-width="180"><template #default="{row}">{{date(row.updated_at)}}</template></ElTableColumn><ElTableColumn label="统计范围"><template #default="{row}">{{row.counted?'直接计入':row.meter_parent_id?'上级覆盖':'观察'}}</template></ElTableColumn></ArtTable></ElCard>
</ElSpace></template>
<script setup>import {computed,ref} from 'vue';import {n,date} from './api';const props=defineProps({snapshot:Object,reports:Object});defineEmits(['navigate']);const liveWindowSeconds=ref(180);const rangeLabel=computed(()=>liveWindowSeconds.value<60?'近 '+liveWindowSeconds.value+' 秒':'近 '+Number((liveWindowSeconds.value/60).toFixed(1))+' 分钟');const value=(v,d)=>v==null?'暂无数据':n(v,d);const meters=computed(()=>props.snapshot.devices.filter(d=>d.capabilities.balance));</script>
